def get_en_lexicon() -> Tuple[Set[str], Set[str]]:
    """Unpack and cache the English word set and prefix set."""
    global _EN_WORDS, _EN_PREFIXES
    if _EN_WORDS is not None and _EN_PREFIXES is not None:
        return _EN_WORDS, _EN_PREFIXES

    words: Set[str] = {"a", "i"}
    prefixes: Set[str] = set("abcdefghijklmnopqrstuvwxyz")

    tag_expand = {"S": "s", "D": "d", "E": "ed", "G": "ing", "L": "ly"}
    prev = ""
    for entry in _PACKED_LEXICON.split("|"):
        if not entry:
            continue
        lcp = int(entry[0], 16)
        body = entry[1:]
        split_i = len(body)
        while split_i > 0 and "A" <= body[split_i - 1] <= "Z":
            split_i -= 1
        word = prev[:lcp] + body[:split_i]
        prev = word
        words.add(word)
        for k in range(2, len(word) + 1):
            prefixes.add(word[:k])
        for tag_ch in body[split_i:]:
            inflected = word + tag_expand[tag_ch]
            words.add(inflected)
            for k in range(len(word) + 1, len(inflected) + 1):
                prefixes.add(inflected[:k])

    for contr in _CONVERSATIONAL_EN_WORDS:
        words.add(contr)
        for k in range(2, len(contr) + 1):
            prefixes.add(contr[:k])

    _EN_WORDS = words
    _EN_PREFIXES = prefixes
    return words, prefixes


def is_en_word(word: str, words: Set[str]) -> bool:
    """Check whether a lowercase token is an attested English word, clitic, or informal form."""
    if word in words:
        return True
    if word == "i'm":
        return True
    for suf in _CLITIC_MOD_SUFFIXES:
        if word.endswith(suf) and len(word) > len(suf):
            stem = word[: -len(suf)]
            if (len(stem) >= 2 or stem == "i") and stem in words:
                return True
    for suf in _CLITIC_PRON_SUFFIXES:
        if word.endswith(suf) and len(word) > len(suf):
            stem = word[: -len(suf)]
            if stem in _PRON_CLITIC_STEMS or (len(stem) >= 3 and stem in words):
                return True
    if word.endswith("in'") and len(word) >= 5 and (word[:-1] + "g") in words:
        return True
    if word.endswith("ish") and len(word) >= 6 and word[:-3] in words:
        return True
    return False


def is_en_prefix(prefix: str, prefixes: Set[str], words: Set[str]) -> bool:
    """Check whether a lowercase character sequence is a valid English word prefix."""
    if prefix in prefixes:
        return True
    idx = prefix.find("'")
    if idx > 0:
        stem = prefix[:idx]
        tail = prefix[idx:]
        if stem == "i" and tail in ("'", "'m", "'d", "'l", "'ll", "'v", "'ve"):
            return True
        if len(stem) >= 2 and stem in words and tail in (
            "'", "'s", "'d", "'l", "'ll", "'r", "'re", "'v", "'ve", "'t"
        ):
            return True
    return False
